 setSlot(unitId,slot){if(!['map','prepare'].includes(this.phase))return this._fail('전투 준비 중에만 배치할 수 있습니다.');if(!int(slot,0,11))return this._fail('배치 칸이 올바르지 않습니다.');const unit=this.roster.find(u=>u.id===unitId);if(!unit)return this._fail('병사를 찾을 수 없습니다.');const other=this.roster.find(u=>u.slot===slot);if(other)other.slot=unit.slot;unit.slot=slot;return this._commit()}
