 _goldFor(node){const e=content().ECONOMY||{},table=e.gold||e.goldRewards||{};let v=table[node.type];if(obj(v))v=v[node.chapter]??v[`chapter${node.chapter}`];return int(v,0,1000)?v:({normal:12,elite:22,boss:30}[node.type]||0)+(node.chapter===2?5:0)}
