 _troopOffers(prefix,onlyRecruit=false,limit=3){const offers=[];if(this.roster.length<12)for(const type of ['spear','archer','support']){const count=Math.min(2,12-this.roster.length);offers.push({id:`${prefix}-recruit-${type}`,category:'troop',kind:'recruit',type,count,name:`${UNIT_NAMES[type]} ${count}명 모집`,description:`컨디션 100인 ${UNIT_NAMES[type]} ${count}명이 합류합니다.`})}if(!onlyRecruit)for(const u of this.roster){if(u.training<2)offers.push({id:`${prefix}-train-${u.id}`,category:'troop',kind:'train',unitId:u.id,name:`${UNIT_NAMES[u.type]} 훈련`,description:`${u.id}번 병사의 훈련을 ${u.training+1}/2로 강화합니다. 컨디션은 유지됩니다.`});for(const type of u.type==='spear'?['guardian','charger']:u.type==='archer'?['sniper','volley']:[])offers.push({id:`${prefix}-evolve-${u.id}-${type}`,category:'troop',kind:'evolve',unitId:u.id,type,name:`${UNIT_NAMES[type]} 진화`,description:`${u.id}번 ${UNIT_NAMES[u.type]}을 ${UNIT_NAMES[type]}으로 진화합니다. 훈련과 컨디션은 유지됩니다.`})}return this._shuffle(offers).slice(0,limit)}
 _rollRarity(source){if(typeof content().rollRarity==='function')return content().rollRarity(()=>this._random(),this.run.chapter,this.run.row,source);const row=this.run.row,chapter=this.run.chapter,w=chapter===1?(row/8<.4?[70,25,5,0,0]:row/8<.6?[60,28,11,1,0]:row/8<.8?[50,30,17,2.9,.1]:[40,32,23,4.9,.1]):row/8<.6?[30,34,28,7.75,.25]:[25,33,31,10.75,.25];if(this._random()<w[4]/100)return'legendary';let n=this._random()*(100-w[4]),tier=0;for(;tier<3;tier++){n-=w[tier];if(n<0)break}if(source==='boss')tier=Math.max(2,Math.min(3,tier+1));else if(source==='elite'&&this._random()<.4)tier=Math.min(3,tier+1);return RARITIES[tier]}
 _relicDescription(id,rarity,stacks){if(typeof content().describeRelic==='function'){const d=content().describeRelic(id,rarity,stacks);if(typeof d==='string')return d;if(obj(d))return d.description||d.text||JSON.stringify(d)}return`${id} · ${rarity} · ${stacks===2?'긍정 효과 1.25배':'기본 효과'}`}
 _relicDefs(){const c=content();return c.RELIC_LIST||((obj(c.RELICS))?Object.values(c.RELICS):Array.isArray(c.RELICS)?c.RELICS:[])}
 _eligibleRelic(id,rarity){if(!this.run.unlockedRelics.includes(id))return false;if(id==='medic'&&!this.roster.some(u=>u.type==='support'))return false;if(id==='drum'&&!this.run.skills.includes('rally'))return false;if(id==='seal'&&!this.roster.some(u=>['spear','guardian','charger'].includes(u.type)))return false;if(id==='spear_tip'&&!this.roster.some(u=>['spear','guardian','charger'].includes(u.type)))return false;const old=this.run.relics.find(r=>r.id===id);return!old||(old.rarity!=='legendary'&&(RARITIES.indexOf(rarity)>RARITIES.indexOf(old.rarity)||old.stacks<2))}
 _relicOffers(prefix,count,source){const out=[],used=[];for(let i=0;i<count;i++){const rarity=this._rollRarity(source),valid=this.run.unlockedRelics.filter(id=>!used.includes(id)&&this._eligibleRelic(id,rarity));if(!valid.length)continue;const id=valid[Math.floor(this._random()*valid.length)],old=this.run.relics.find(r=>r.id===id),action=old?(RARITIES.indexOf(rarity)>RARITIES.indexOf(old.rarity)?'replace':'merge'):'equip';used.push(id);const def=this._relicDefs().find(r=>r.id===id);const effect=action==='merge'?this._relicDescription(id,old.rarity,2):this._relicDescription(id,rarity,1);out.push({id:`${prefix}-relic-${i}-${id}`,category:'relic',kind:'relic',name:`${def?.name||id} · ${rarity}`,description:`${effect}${old?` / 현재: ${this._relicDescription(old.id,old.rarity,old.stacks)} / ${action==='merge'?'현재 등급 유지, 한 슬롯에서 2중첩':'새 등급 1중첩으로 교체'}`:''}`,relic:{id,rarity,stacks:1},action,existing:old?clone(old):null,requiresReplacement:!old&&this.run.relics.length>=3})}return out}
 _makeReward(){const prefix=`reward-${this.run.currentNodeId}`,tutorial=this.run.tutorial&&this.run.history.filter(h=>h.win).length===1,troop=this._troopOffers(prefix,tutorial),relic=tutorial?[]:this._relicOffers(prefix,3,this.currentNode.type),offers={troop,relic};return{id:prefix,nodeId:this.run.currentNodeId,categories:['troop','relic'].filter(c=>offers[c].length),offers,previewCategory:null,claimed:false}}
