 _canApply(offer,replaceRelicId){if(!offer)return this._fail('보상 후보를 찾을 수 없습니다.');if(offer.kind==='recruit')return this.roster.length+offer.count<=12||this._fail('군단은 최대 12명입니다.');if(offer.kind==='train'){const u=this.roster.find(u=>u.id===offer.unitId);return!!u&&u.training<2||this._fail('더 훈련할 수 없는 병사입니다.')}if(offer.kind==='evolve'){const u=this.roster.find(u=>u.id===offer.unitId);return!!u&&(u.type==='spear'?['guardian','charger']:u.type==='archer'?['sniper','volley']:[]).includes(offer.type)||this._fail('진화할 수 없는 병사입니다.')}if(offer.kind==='relic'){if(!this._eligibleRelic(offer.relic.id,offer.relic.rarity))return this._fail('현재 사용할 수 없는 유물입니다.');const old=this.run.relics.find(r=>r.id===offer.relic.id);if(old)return true;if(this.run.relics.length<3)return true;return this.run.relics.some(r=>r.id===replaceRelicId)||this._fail('교체할 유물 하나를 선택해 주세요.')}return this._fail('알 수 없는 보상입니다.')}
