 claimReward(offerId,replaceRelicId){const p=this.run.pendingReward;if(this.phase!=='reward'||!p||p.claimed)return this._fail('받을 수 있는 보상이 없습니다.');const offer=[...p.offers.troop,...p.offers.relic].find(o=>o.id===offerId);if(!this._canApply(offer,replaceRelicId))return false;this._apply(offer,replaceRelicId);p.claimed=true;p.previewCategory=offer.category;this.run.phase='nodeComplete';return this._commit()}
