 _makeShop(){const prefix=`shop-${this.run.currentNodeId}`,offers=this._relicOffers(prefix,2,'shop');const troops=this._troopOffers(prefix,false,100);const recruit=troops.find(o=>o.kind==='recruit'),train=troops.find(o=>o.kind==='train');if(recruit)offers.push({...recruit,count:1,name:`${UNIT_NAMES[recruit.type]} 1명 모집`,description:`컨디션 100인 ${UNIT_NAMES[recruit.type]} 1명이 합류합니다.`});if(train)offers.push(train);return offers.map(o=>({...o,price:o.kind==='relic'?this._relicPrice(o.relic.rarity):(content().ECONOMY?.prices?.[o.kind]??(o.kind==='recruit'?20:30)),purchased:false}))}
