 leaveShop(){if(this.phase!=='shop')return this._fail('상점에 있지 않습니다.');this._completeNode();return this._commit()}
 rest(choice){if(this.phase!=='rest'||!['recover','prepare'].includes(choice))return this._fail('휴식 선택이 올바르지 않습니다.');const option=(content().REST_OPTIONS||[{id:'recover',recover:35,prepared:false},{id:'prepare',recover:10,prepared:true}]).find(o=>o.id===choice);for(const unit of this.roster)unit.condition=Math.min(100,unit.condition+option.recover);if(option.prepared)this.run.prepared=true;this._completeNode();return this._commit()}
